    "category": "ogtt",
    "direction": "higher_more_sensitive",
    "formula_latex": "\\frac{(75000 + (G_{0,mg/dL} - G_{120,mg/dL})\\cdot 0.19\\cdot BW)/120}{MPG_{mmol/L}\\cdot \\log_{10} MSI_{\\mu U/mL}}",
